import re


class MessageFilter(object):

    def __init__(self, msg_regex):
        """

        :param msg_regex: message regex which need to search in LogEntries. Eg.(.*setcred grantors.* or "AUDIT1110.*")
        """
        self.msg_regex = msg_regex

    def __call__(self, journal_entries):
        """

        :param journal_entries: List of JournalEntries
        :return: filtered list of JournalEntries containing expected message
        """

        for journal_entry in journal_entries:
            if re.match(self.msg_regex, journal_entry.message):
                yield journal_entry
